import sys
from collections import deque


def main():
    data = sys.stdin.buffer.read().split()
    n, m, s = int(data[0]), int(data[1]), int(data[2])
    edges = []
    adj = [[] for _ in range(n)]
    idx = 3
    for _ in range(m):
        u, v, w = int(data[idx]), int(data[idx + 1]), int(data[idx + 2])
        idx += 3
        edges.append((u, v, w))
        adj[u].append(v)
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    for _ in range(n - 1):
        changed = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            break
    neg = [False] * n
    q = deque()
    for u, v, w in edges:
        if dist[u] != INF and dist[u] + w < dist[v] and not neg[v]:
            neg[v] = True
            q.append(v)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not neg[v]:
                neg[v] = True
                q.append(v)
    out = []
    for v in range(n):
        if neg[v]:
            out.append('-INF')
        elif dist[v] == INF:
            out.append('UNREACHABLE')
        else:
            out.append(str(dist[v]))
    sys.stdout.write('\n'.join(out) + '\n')


main()

