import sys


def main():
    data = sys.stdin.read().split()
    n, m, s = int(data[0]), int(data[1]), int(data[2])
    out_edges = [[] for _ in range(n)]
    for i in range(m):
        u, v, w = int(data[3 + 3 * i]), int(data[4 + 3 * i]), int(data[5 + 3 * i])
        out_edges[u].append((v, w))

    def reach_from(starts):
        seen = set(starts)
        stack = list(starts)
        while stack:
            u = stack.pop()
            for v, _ in out_edges[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        return seen

    on_neg_cycle = set()

    def cycles(start, u, total, path):
        for v, w in out_edges[u]:
            if v == start:
                if total + w < 0:
                    on_neg_cycle.update(path)
            elif v not in path:
                path.append(v)
                cycles(start, v, total + w, path)
                path.pop()

    for c in range(n):
        cycles(c, c, 0, [c])

    reachable = reach_from([s])
    bad = reach_from([c for c in on_neg_cycle if c in reachable])

    best = {}

    def paths(u, total, visited):
        if u not in best or total < best[u]:
            best[u] = total
        for v, w in out_edges[u]:
            if v not in visited:
                visited.add(v)
                paths(v, total + w, visited)
                visited.remove(v)

    paths(s, 0, {s})
    for v in range(n):
        if v in bad:
            print('-INF')
        elif v not in reachable:
            print('UNREACHABLE')
        else:
            print(best[v])


main()

